import{_ as n,o as a,c as l,aj as p}from"./chunks/framework.BdtAaXf2.js";const t="/assets/1.CemFPDtT.gif",i="/assets/2.Nm-XgP9S.gif",h="/assets/3.CX-gMMZT.gif",e="/assets/image-20240816011629339.CKVux8r3.png",k="/assets/image-20240816012146982.p6LAg3b9.png",F=JSON.parse('{"title":"HarmonyOS Next 动画大全02-显式动画","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全02-显式动画/HarmonyOS Next 动画大全02-显式动画.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全02-显式动画/HarmonyOS Next 动画大全02-显式动画.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next 动画大全02-显式动画\\n\\n## 前言\\n\\n上一篇文章我们介绍过属性动画`animation`的使用方法，那么本文就来学习和了解一下显示动画`animateTo`\\n\\n## animateTo\\n\\n我们称之为**显式动画**，它本身是一个全局函数，通过调用函数的形式实现动画效果。**显式动画**`animateTo`和之前的**属性动画**\\n\\n`animation`最大的区别在于 显式动画可以利用本身函数的特性实现多个显式动画连续调用，从而实现连贯性的动画。\\n\\n## 基本语法\\n\\n`animateTo(value: AnimateParam, event: () => void): void`\\n\\n| 参数  | 类型         | 是否必填 | 描述                   |\\n| ----- | ------------ | -------- | ---------------------- |\\n| value | AnimateParam | 是       | 设置动画效果相关参数。 |\\n| event | () => void   | 是       | 指定动效的闭包函数     |\\n\\n解释：\\n\\n1. `AnimateParam`  动画属性，在上一篇文章**《HarmonyNext动画大全01-属性动画》**内有详细介绍过\\n\\n   | 名称         | 描述                                            | 示例            |\\n   | ------------ | ----------------------------------------------- | --------------- |\\n   | duration     | 动画执行时间，单位毫秒                          | 1000            |\\n   | tempo        | 动画执行速度，默认是1，最小是0                  | 1               |\\n   | curve        | 动画曲线 比如匀速、先快后慢等                   | Curve.linear    |\\n   | delay        | 延迟时间 单位毫秒                               | 1000            |\\n   | iterations   | 动画执行次数，-1 为无限                         | 1               |\\n   | playMode     | 动画播放模式 如播放两次时，每次都是从头开始播放 | PlayMode.Normal |\\n   | **onFinish** | 动画结束的回调函数                              |                 |\\n\\n   其中，**onFinish** 是我们实现连续动画的关键\\n\\n2. `event`   指定动效的闭包函数\\n\\n## 基本示例\\n\\n![1](readme.assets/1.gif)\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  scaleXY: number = 1\\n\\n  build() {\\n    Column() {\\n      Button(\\"点我就变大啦\\")\\n        .scale({ x: this.scaleXY, y: this.scaleXY })\\n        .onClick(() => {\\n          //   显式动画\\n          animateTo({\\n            // 1 指定动画参数\\n            duration: 1000\\n          }, () => {\\n            // 2 指定动效的闭包函数\\n            this.scaleXY = 2\\n          })\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .padding(40)\\n  }\\n}\\n```\\n\\n**代码解释**：\\n\\n1. 可以看到 `animateTo`就是一个全局函数，可以直接调用\\n2. ` duration: 1000`  表示动画参数，动画的持续时间为1s\\n3. `this.scaleXY = 2` 放在 `animateTo`的第二个参数上，回调函数，也是在这里指定要具体执行的动画效果\\n\\n\\n\\n至此，我们发现 显式动画 `animateTo` 和 之前的属性动画 `animation` 没有太大区别。 对的，因为他们两个最大的区别就在于 `animateTo` 可以比较方便实现**连续多个动画效果**。\\n\\n\\n\\n## 连续多个动画效果\\n\\n如下图：\\n\\n![2](readme.assets/2.gif)\\n\\n可以看到以上动画其实是有多个动画效果组合在一起的。如\\n\\n1. **左上角 ->  右上角**\\n2. **右上角 -> 右下角**\\n3. **右下角 -> 左下角**\\n4. **左下角 -> 左上角**\\n\\n我们思考：该如何实现呢？ \\n\\n答案是：**onFinish**。 `onFinish`  是动画参数中的一个属性，表示动画执行完毕。\\n\\n## onFinish\\n\\n当动画执行完毕时，便会自动触发 `onFinish`里面的逻辑\\n\\n![3](readme.assets/3.gif)\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  x: number = 0\\n  @State\\n  y: number = 0\\n\\n  build() {\\n    Column() {\\n      Row()\\n        .width(100)\\n        .height(100)\\n        .backgroundColor(\\"#499C54\\")// tips: translate 表示设置位移\\n        .translate({\\n          x: this.x,\\n          y: this.y\\n        })\\n        .onClick(() => {\\n          animateTo({\\n            // 动画执行完毕触发\\n            onFinish: () => {\\n              AlertDialog.show({ message: \\"动画执行完毕\\" })\\n            }\\n          }, () => {\\n            this.x = 100\\n            this.y = 0\\n          })\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .alignItems(HorizontalAlign.Start)\\n\\n  }\\n}\\n```\\n\\n\\n\\n因此，当我们想要实现连续执行多个动画时，就不断往`onFinish`里面**套娃**即可\\n\\n![2](readme.assets/2.gif)\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  x: number = 0\\n  @State\\n  y: number = 0\\n\\n  build() {\\n    Column() {\\n      Row()\\n        .width(100)\\n        .height(100)\\n        .backgroundColor(\\"#499C54\\")\\n        .translate({\\n          x: this.x,\\n          y: this.y\\n        })\\n        .onClick(() => {\\n          // 1 左上角 -> 右上角\\n          animateTo({\\n            onFinish: () => {\\n              // 2 右上角 -> 右下角\\n              animateTo({\\n                onFinish: () => {\\n                  // 3 右下角 -> 左下角\\n                  animateTo({\\n                    onFinish: () => {\\n                      // 4 左下角 -> 左上角\\n                      animateTo({}, () => {\\n                        this.x = 0\\n                        this.y = 0\\n                      })\\n                    }\\n                  }, () => {\\n                    this.x = 0\\n                    this.y = 100\\n                  })\\n                }\\n              }, () => {\\n                this.x = 100\\n                this.y = 100\\n              })\\n            }\\n          }, () => {\\n            this.x = 100\\n            this.y = 0\\n          })\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .alignItems(HorizontalAlign.Start)\\n\\n  }\\n}\\n```\\n\\n以上这个代码，就可以实现连续动画了。\\n\\n## 回调函数地狱\\n\\n---\\n\\n但是，这个代码结构，妈妈看到了很难不夸你写得好 \\n\\n![image-20240816011629339](readme.assets/image-20240816011629339.png)\\n\\n以上结构已经形成了一个回调函数地狱了，小伙伴们~😂\\n\\n\\n\\n## 解决回调函数地狱\\n\\n有开发经验的小伙们应该可以马上想到解决方法\\n\\n1. `promise` \\n2. `async` 和 `await` \\n\\n对的，回调函数地狱可以靠这两个老哥来解决。\\n\\n\\n\\n先拿 `animateTo`    和 `Promise` 做一个封装\\n\\n```typescript\\nconst animateToPromise = (option: AnimateParam, fn: Function) => {\\n  const promise: Promise<undefined> = new Promise((resolve: Function) => {\\n    option.onFinish = () => {\\n      resolve()\\n    }\\n    animateTo(option, () => {\\n      fn()\\n    })\\n  })\\n  return promise\\n}\\n```\\n\\n最后再来看解决后的版本\\n\\n```typescript\\n  Row() {\\n\\n  }\\n  .width(100)\\n  .height(100)\\n  .backgroundColor(\\"#499C54\\")\\n  .translate({ x: this.x, y: this.y })\\n  .onClick(async () => {\\n    // 1 左上角 -> 右上角\\n    await animateToPromise({}, () => {\\n      this.x = 100\\n      this.y = 0\\n    })\\n    // 2 右上角 -> 右下角\\n    await animateToPromise({}, () => {\\n      this.x = 100\\n      this.y = 100\\n    })\\n    // 3 右下角 -> 左下角\\n    await animateToPromise({}, () => {\\n      this.x = 0\\n      this.y = 100\\n    })\\n    // 4 左下角 -> 左上角\\n    await animateToPromise({}, () => {\\n      this.x = 0\\n      this.y = 0\\n    })\\n  })\\n```\\n\\n---\\n\\n可以看到，封装后的代码，要简洁不少\\n\\n![image-20240816012146982](readme.assets/image-20240816012146982.png)\\n\\n## 小结\\n\\n1. `animateTo` 适合用在连续多个动画效果上\\n2. `animateTo` 可以搭配`promise` 和`async`、`await` 解决回调地狱的问题\\n3. 由于篇幅问题，这里没有直接介绍promise和async。"}'),r={name:"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全02-显式动画/HarmonyOS Next 动画大全02-显式动画.md"};function E(d,s,g,y,c,o){return a(),l("div",null,[...s[0]||(s[0]=[p("",50)])])}const m=n(r,[["render",E]]);export{F as __pageData,m as default};
